using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using NWH.VehiclePhysics2;using NWH.VehiclePhysics2.Damage;using LWS.TruckSports;
namespace LWS.TruckDerby {
// NWH remains the sole powertrain, tire, suspension and visible deformation authority.
public sealed class DerbyFighter:MonoBehaviour {
 public DerbyMatch match;public int slot;public VehicleController vehicle;public Rigidbody body;public DamageHandler deform;public Transform assembly,intact,cabSeat;public SportsFragmentRig fragments;public DerbyMirrors mirrors;public ParticleSystem smoke,fire,sparks,leak;public Renderer paint;public SportsNwhDamageAdapter performance;
 public readonly DerbyDamageState damage=new DerbyDamageState();public readonly DerbyMotionWatch motion=new DerbyMotionWatch();public float Rollover{get;private set;}public bool Eliminated{get;private set;}public Vector3 Incoming{get;private set;}public Vector3 IncomingAngular{get;private set;}public int QualifyingContacts{get;private set;}public int DetachedWheels{get;private set;}public float FireAge{get;private set;}public float ContactAge{get;private set;}public float LastImpact{get;private set;}=-100;public int ContactOther{get;private set;}=-1;float contactStamp=-100;
 readonly int[] contacts=new int[24];readonly float[] contactTimes=new float[24];int contactCursor;float sampleDamageAt;MaterialPropertyBlock tint;Vector3 initialCom;bool initialized;Vector3 visualScale;float nextWarning;MeshFilter[] originalFilters;Mesh[] pristine;
 void Awake(){originalFilters=fragments.sourceRenderers.Select(r=>r.GetComponent<MeshFilter>()).Where(f=>f!=null).ToArray();pristine=originalFilters.Select(f=>f.sharedMesh).ToArray();initialCom=body.centerOfMass;visualScale=intact.localScale;tint=new MaterialPropertyBlock();initialized=true;}
 // NWH OnDisable cancels RevLimiterCoroutine before it can clear its public latch. A fresh heat must not inherit that torque cut.
 public void ResetFighter(Vector3 p,Quaternion q){if(!initialized)Awake();vehicle.enabled=false;body.isKinematic=true;body.detectCollisions=true;gameObject.SetActive(true);Eliminated=false;RepairAndDrain();performance.Repair();vehicle.powertrain.engine.revLimiterActive=false;fragments.ResetBody();intact.localScale=visualScale;damage.Reset();Rollover=FireAge=ContactAge=0;ContactOther=-1;contactStamp=LastImpact=-100;QualifyingContacts=DetachedWheels=0;Array.Clear(contacts,0,contacts.Length);Array.Clear(contactTimes,0,contactTimes.Length);contactCursor=0;body.position=p;body.rotation=q;transform.SetPositionAndRotation(p,q);body.linearVelocity=body.angularVelocity=Vector3.zero;body.centerOfMass=initialCom;motion.Reset(body.worldCenterOfMass);tint.SetColor("_BaseColor",match.setup.players[slot].color);paint.SetPropertyBlock(tint);foreach(var fx in new[]{smoke,fire,sparks,leak})fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);vehicle.input.states.Reset();vehicle.input.autoSetInput=false;sampleDamageAt=nextWarning=0;}
 // A new vendor handler drains its private pending work queue without reflection or vendor edits.
 // Public Repair restores NWH meshes/powertrain before replacement; only owned runtime mesh clones are released.
 void RepairAndDrain(){var old=deform;old.enabled=false;var generated=new HashSet<Mesh>();for(int i=0;i<originalFilters.Length;i++){var mesh=originalFilters[i].sharedMesh;if(mesh!=null&&mesh!=pristine[i])generated.Add(mesh);}old.Repair();deform=gameObject.AddComponent<DamageHandler>();deform.visualOnly=true;deform.decelerationThreshold=1e9f;deform.deformationRadius=old.deformationRadius;deform.deformationStrength=old.deformationStrength;deform.deformationRandomness=old.deformationRandomness;deform.deformationVerticesPerFrame=old.deformationVerticesPerFrame;deform.collisionIgnoreTags=new List<string>(old.collisionIgnoreTags);deform.deformationIgnoreTags=new List<string>(old.deformationIgnoreTags);Destroy(old);foreach(var piece in fragments.pieces)piece.renderer.GetComponent<MeshFilter>().sharedMesh=piece.source.GetComponent<MeshFilter>().sharedMesh;foreach(var mesh in generated)Destroy(mesh);}
 public void Wake(){body.isKinematic=false;vehicle.enabled=true;vehicle.input.autoSetInput=false;motion.Reset(body.worldCenterOfMass);}
 public void Drive(Vector2 input,float dt){if(Eliminated)return;ContactAge=ContactOther>=0&&Time.fixedTime-contactStamp<.06f?ContactAge+dt:0;vehicle.input.autoSetInput=false;vehicle.input.Steering=input.x;vehicle.input.Vertical=input.y;vehicle.input.Handbrake=0;float up=Vector3.Dot(transform.up,Vector3.up);Rollover=up<.05f?Rollover+dt:Mathf.Max(0,Rollover-dt*2);if(up<.2f&&input.sqrMagnitude>.1f){var axis=Vector3.Cross(transform.up,Vector3.up);if(axis.sqrMagnitude<.03f)axis=transform.forward;body.AddTorque(axis.normalized*1.6f-body.angularVelocity*.4f,ForceMode.Acceleration);}bool stopped=motion.Tick(body.worldCenterOfMass,dt);if(motion.Stopped>3&&Time.time>=nextWarning){match.feedback.Play(4,0,true);nextWarning=Time.time+.55f;if(!smoke.isPlaying)smoke.Play();}if(motion.Stopped<1&&damage.Engine<=.65f&&damage.Structure<=.7f&&smoke.isPlaying)smoke.Stop();if(damage.Engine>.65f||damage.Structure>.7f){FireAge+=dt;if(!smoke.isPlaying)smoke.Play();if(FireAge>1.5f&&!fire.isPlaying)fire.Play();}if(damage.Engine>.92f){damage.Apply(DerbyZone.Engine,dt*.025f);performance.Apply(damage.Engine,damage.zones[(int)DerbyZone.Rear]*.4f,damage.wheels);}if(stopped)match.QueueElimination(slot,"STOPPED FOR FIVE SECONDS");else if(Rollover>4)match.QueueElimination(slot,"UNRECOVERABLE ROLLOVER");else if(damage.Destroyed)match.QueueElimination(slot,"CHASSIS DESTROYED");else if(damage.Engine>=1&&motion.MeasuredSpeed<.3f&&FireAge>4)match.QueueElimination(slot,"ENGINE FIRE");else if(body.position.y< -12)match.QueueElimination(slot,"OUT OF ARENA");Incoming=body.linearVelocity;IncomingAngular=body.angularVelocity;}
 void OnCollisionEnter(Collision c){if(!match.Live||match.Stage!=DerbyStage.Playing||Eliminated||c.collider.isTrigger)return;var other=c.rigidbody;int identity=other!=null?other.GetInstanceID():c.collider.GetInstanceID();for(int i=0;i<contacts.Length;i++)if(contacts[i]==identity&&Time.fixedTime-contactTimes[i]<.45f)return;float best=0;ContactPoint chosen=default;var opponent=other!=null?other.GetComponent<DerbyFighter>():null;for(int i=0;i<c.contactCount;i++){var point=c.GetContact(i);var speed=Incoming+Vector3.Cross(IncomingAngular,point.point-body.worldCenterOfMass);var otherSpeed=opponent!=null?opponent.Incoming+Vector3.Cross(opponent.IncomingAngular,point.point-other.worldCenterOfMass):other!=null?other.GetPointVelocity(point.point):Vector3.zero;float normal=Mathf.Max(0,-Vector3.Dot(speed-otherSpeed,point.normal));if(normal>best){best=normal;chosen=point;}}float intensity=DerbyDamageState.Impact(best,body.mass,other!=null?other.mass:0,c.impulse.magnitude);if(intensity<=0)return;contacts[contactCursor]=identity;contactTimes[contactCursor]=Time.fixedTime;contactCursor=(contactCursor+1)%contacts.Length;var local=transform.InverseTransformPoint(chosen.point);DerbyZone zone=local.y>2.7f?DerbyZone.Roof:Mathf.Abs(local.z)>Mathf.Abs(local.x)*1.4f?(local.z>0?DerbyZone.Front:DerbyZone.Rear):(local.x<0?DerbyZone.Left:DerbyZone.Right);if(local.y>1.2f&&local.z>0&&zone!=DerbyZone.Roof)zone=DerbyZone.Cab;int wheel=-1;float closest=1.2f;for(int i=0;i<vehicle.powertrain.wheelCount;i++){float d=Vector3.Distance(chosen.point,vehicle.powertrain.wheels[i].wheelUAPI.WheelPosition);if(d<closest){closest=d;wheel=i;}}damage.Apply(zone,intensity,wheel);QualifyingContacts++;LastImpact=Time.fixedTime;performance.Apply(damage.Engine,damage.zones[(int)DerbyZone.Rear]*.4f,damage.wheels);if(intensity>.025f)deform.Enqueue(c,Mathf.Clamp(intensity*2400,70,1560));sparks.transform.position=chosen.point;sparks.Play();if(intensity>.07f){leak.transform.position=chosen.point;leak.Play();}sampleDamageAt=Time.time+.35f;match.Hit(slot,opponent!=null?opponent.slot:-1,best,intensity,chosen.point);}
 // Observe sustained truck contact for AI disengagement only; it never repeats damage or changes outcomes.
 void OnCollisionStay(Collision c){if(!match.Live||match.Stage!=DerbyStage.Playing||Eliminated||c.rigidbody==null)return;var other=c.rigidbody.GetComponent<DerbyFighter>();if(other==null||other.Eliminated)return;if(ContactOther!=other.slot)ContactAge=0;ContactOther=other.slot;contactStamp=Time.fixedTime;}
 public void Eliminate(string reason){if(Eliminated)return;Eliminated=true;vehicle.input.states.Reset();vehicle.enabled=false;mirrors.Show(false);if(!fire.isPlaying)fire.Play();fragments.Burst();match.feedback.Play(3,0,true);match.Pulse(slot,.6f,.2f);}
 public void Freeze(){vehicle.input.states.Reset();vehicle.enabled=false;body.isKinematic=true;fragments.Freeze();mirrors.Show(false);}
 void LateUpdate(){vehicle.soundManager.masterVolume=match.Live&&Application.isFocused?match.settings.sfx*.35f:0;}
 public void StopSound(){foreach(var source in GetComponentsInChildren<AudioSource>())source.Stop();}
}}
